const token = jwt.sign({ userId: 123 }, process.env.APP_SECRET, { expiresIn: '1h' });
console.log(token);

try {
  const decoded = jwt.verify(token, process.env.APP_SECRET);
  console.log(decoded);
} catch (err) {
  console.error('Token verification failed:', err.message);
}

