// Example of validating a JSON object structure in TypeScript
function validateProduct(product: any): boolean {
  if (typeof product.name !== 'string' || product.name.trim() === '') {
    return false;
  }
  // Additional validation logic for other properties can be added here
  return true;
}

// Example usage
const product = { name: 'Sample Product', price: '20' };
console.log(validateProduct(product)); // Should return true if valid
